// Parameter (ALLY 44, Briefings): Sitzung und geprüfte Parameter für talents_briefings_web (briefing = Nummer, papierkorb = 1).
const E = $input.first().json;
const P = E.parameter || {};
const f = {};
if (/^[0-9]{1,9}$/.test(String(P.briefing || ''))) f.briefing = String(P.briefing);
if (String(P.papierkorb || '') === '1') f.papierkorb = '1';
return [{ json: { werte: [/^[0-9a-f]{64}$/.test(String(E.sitzung || '')) ? String(E.sitzung) : '', JSON.stringify(f)] } }];

