-- Daten laden (ALLY 44): Seite Briefings (talents_briefings_web prüft Sitzung, Paket, Recht und Sichtbarkeit je Briefing)
SELECT s.person IS NOT NULL AS ok, CASE WHEN s.person IS NOT NULL THEN talents_briefings_web($1::text, $2::jsonb) END AS r
FROM (SELECT 1) x LEFT JOIN LATERAL (SELECT * FROM ally_ui_sitzung($1::text) y WHERE NOT y.muss_pw_setzen) s ON true;

