// KI-Analysen (ALLY 44, Migration 177 B10b, Migration 180; Koordinator 30.10.2026, Stefan: „es ist kein briefing“, „alles … muss komplett einstellbar sein auch
// zeitlich“, „das muss alles vorher passieren“, „zudem fehlen hier viele infos wie z.B. wann das briefing erstellt wurde“). Daten und Rechte aus talents_briefings_web.
// Ansichten: Liste (Kopfknopf „Neue Analyse“ öffnet die Einstellungen; „Erstellen“ legt an und zeigt sofort das Ergebnis; „Papierkorb“), Analyse (briefing=<Nummer>:
// Ergebnis mit Kopf und vollem Text, Kacheln Name und Talents, Zeitplan, Empfänger, Zustellung, Teilen; Verlauf mit allen lesbaren Ergebnissen; ergebnis=<Nummer>
// zeigt ein älteres; „Jetzt erstellen“ zeigt die Einstellungen kurz an, dann das Ergebnis), Papierkorb (papierkorb=1).
// Sehen: selbst angelegt, selbst Empfänger, geteilt (Recht „KI-Analysen“, eigene) bzw. alle; ändern, teilen, löschen: wer sie angelegt hat, und Admins.
// Jede Analyse, auch die Standard-Analyse, lässt sich in den Papierkorb legen und endgültig löschen (Stefan 30.10.2026). Teilen statt „Freigabe“ (Stefan 30.10.2026).
// Stefans Regel (Koordinator 29.10.2026): Hinweise nur im i an der Überschrift bzw. am Feld, nie als Zeile. Als Zeile nur Stand (Werte, „Fixiert.“, Warnungen) und Leerzustände.
const E = $('Start').first().json;
const D = $('Daten laden').first().json || {};
const F = E.funktion || {};
const P = E.parameter || {};
const s = v => String(v ?? '');
const L = x => Array.isArray(x) ? x : [];
const id9 = v => /^[0-9]{1,9}$/.test(s(v)) ? s(v) : '';
const id12 = v => /^[0-9]{1,12}$/.test(s(v)) ? s(v) : '';
const SEITE = 'briefings';
const titel = s(F.name || 'KI-Analysen');
const hier = p => ({ seite: SEITE, parameter: p || {} });
const krumen0 = [{ text: 'Startseite', ziel: { seite: 'start' } }, { text: 'Dashboard', ziel: { seite: 'talents' } }];
const kopf = { schluessel: SEITE, art: 'funktion', titel, beschreibung: s(F.beschreibung || ''), krumen: krumen0.concat([{ text: titel }]) };
const R = D.r;
if (D.ok !== true || !R || R.ok !== true)
  return [{ json: { inhalt: { seite: kopf, bloecke: [{ typ: 'hinweis', ton: 'warn', text: s((R && R.fehler) || 'Die KI-Analysen konnten nicht geladen werden. Bitte neu laden.') }] } } }];
const zusammen = (...t) => t.filter(Boolean).join(' · ');
const anzE = n => Number(n) === 1 ? '1 Empfänger' : Number(n || 0) + ' Empfänger';
const TAGE = ['Montag', 'Dienstag', 'Mittwoch', 'Donnerstag', 'Freitag', 'Samstag', 'Sonntag'];
const INTERVALLE = [{ wert: 'aus', text: 'Nur von Hand' }, { wert: 'tag', text: 'Täglich' }, { wert: 'woche', text: 'Wöchentlich' }, { wert: 'monat', text: 'Monatlich' }];
const ZUST = [{ wert: 'ally', text: 'Nur in Ally' }, { wert: 'chat', text: 'Chat' }, { wert: 'mail', text: 'Mail' }];
const ZR = L(R.zeitraeume).length ? L(R.zeitraeume) : [{ wert: 'letzte_7_tage', text: 'Letzte 7 Tage' }, { wert: 'letzte_30_tage', text: 'Letzte 30 Tage' }, { wert: 'vormonat', text: 'Vormonat' }];
const SYSA = R.system_absender && typeof R.system_absender === 'object' ? R.system_absender : null;
const ABS = L(R.auswahl_absender).filter(a => a && s(a.adresse));
const absName = a => { const p0 = ABS.find(x => s(x.adresse) === s(a)); return p0 && s(p0.name) !== s(a) ? s(p0.name) + ' (' + s(a) + ')' : s(a); };
const absOpt = () => [{ wert: '', text: SYSA ? 'Absender für Systemnachrichten (' + s(SYSA.adresse) + ')' : 'Bitte ein Postfach wählen' }]
  .concat(ABS.map(a => ({ wert: s(a.adresse), text: absName(a.adresse) + (a.versand === true ? '' : a.anders === true ? ' – kann keine KI-Analysen senden' : a.gesperrt === true ? ' – Versand ausgeschaltet' : ' – Versand nicht eingerichtet') })));
const ABS_INFO = 'Von diesem Postfach kommt die Mail. Zur Auswahl stehen Postfächer mit eigenem Ablauf, die du als Absender wählen darfst; senden kann es mit geprüftem und erlaubtem Versand (Einstellungen › Meine Postfächer bzw. Gemeinsame Postfächer).';
const ZEIT_INFO = 'Verglichen wird mit dem gleich langen Zeitraum davor (Vormonat: mit dem Monat davor). Die letzten 7 bzw. 30 Tage enden gestern.';
const PLAN_INFO = 'Wann Ally die KI-Analyse von selbst erstellt. Ohne Zeitplan („Nur von Hand“) entsteht sie nur mit „Jetzt erstellen“. Monatlich: Tag 1 bis 28.';
const ZUST_INFO = 'Nur in Ally: Das Ergebnis steht auf dieser Seite und im Dashboard, sonst nirgends. Chat bzw. Mail: zusätzlich als Nachricht von Ally im Chat bzw. an die Mail-Adresse des Zugangs, soweit eingerichtet.';
const TAL_INFO = 'Jede Person bekommt ihre eigenen Talents (für die sie zuständig ist) und dazu die weiteren Talents, soweit sie sie sehen darf.';
// Zeitplan-Felder (neu und Kachel): Häufigkeit, Wochentag bzw. Tag im Monat, Uhrzeit
const planFelder = (w0, f) => [
  f({ typ: 'auswahl', name: 'intervall', label: 'Zeitplan', breite: 'voll', ausklappliste: true, wert: s(w0.intervall || 'aus'), optionen: INTERVALLE, info: PLAN_INFO }),
  f({ typ: 'auswahl', name: 'tag', label: 'Wochentag', ausklappliste: true, wert: s(Number(w0.tag) <= 7 ? w0.tag : '1'), optionen: TAGE.map((t, i) => ({ wert: String(i + 1), text: t })),
    zeigen_wenn: { feld: 'intervall', werte: ['woche'] } }),
  f({ typ: 'auswahl', name: 'monatstag', label: 'Tag im Monat', ausklappliste: true, wert: s(w0.intervall === 'monat' ? w0.tag : '1'),
    optionen: Array.from({ length: 28 }, (_, i) => ({ wert: String(i + 1), text: (i + 1) + '.' })), zeigen_wenn: { feld: 'intervall', werte: ['monat'] } }),
  f({ typ: 'zeit', name: 'uhrzeit', label: 'Uhrzeit', wert: s(w0.uhrzeit || '08:00'), schritt: 900, info: 'Im 15-Minuten-Takt, deutsche Zeit.', zeigen_wenn: { feld: 'intervall', werte: ['tag', 'woche', 'monat'] } })];
// Layout 5 (Plan 31, E8): Mehrfachauswahl mit den gewählten Einträgen zuerst (Stand beim Laden), sonst Reihenfolge wie geliefert
const gewZuerst = (O, wert) => { const g = new Set(L(wert).map(s)); return O.filter(o => g.has(s(o.wert))).concat(O.filter(o => !g.has(s(o.wert)))); };
// Text eines Ergebnisses in Bausteine wie im Dashboard (ALLY 24): Absätze; mehrzeilige Absätze mit kurzer erster Zeile = Überschrift und Liste
const bausteine = t => {
  const aus = [];
  for (const abs of String(t || '').split(/\n{2,}/)) {
    const z = abs.split('\n').map(x => x.trim()).filter(Boolean);
    if (!z.length) continue;
    if (z.length === 1) { aus.push({ typ: 'text', text: z[0] }); continue; }
    let start = 0;
    if (/:$/.test(z[0]) || (z[0].length <= 60 && !/^[-•]/.test(z[0]))) { aus.push({ typ: 'unterueberschrift', text: z[0].replace(/:$/, '') }); start = 1; }
    aus.push({ typ: 'liste', eintraege: z.slice(start).map(x => ({ text: x.replace(/^[-•]\s*/, '') })) });
  }
  return aus.length ? aus : [{ typ: 'text', ton: 'grau', text: 'Kein Text gespeichert.' }];
};
let abschnitte = [], bloecke = null;
const fenster = [];
const B = R.briefing && typeof R.briefing === 'object' && id9(R.briefing.id) ? R.briefing : null;

if (id9(P.briefing) && !B) {
  kopf.krumen = krumen0.concat([{ text: titel, ziel: hier() }, { text: 'KI-Analyse' }]);
  bloecke = [{ typ: 'hinweis', ton: 'warn', text: 'Diese KI-Analyse gibt es nicht oder sie ist nicht mit dir geteilt.' }, { typ: 'aktion', text: 'Zu den KI-Analysen', ziel: hier() }];
} else if (B) {
  // ---------- Analyse ----------
  const bid = id9(B.id), w = { briefing_id: bid }, darf = B.darf_aendern === true && B.geloescht !== true;
  const EL = L(B.empfaenger_liste), ER = L(B.ergebnisse), OHNE = L(B.gewaehlt_ohne);
  const Z = B.zeitraum_text && typeof B.zeitraum_text === 'object' ? B.zeitraum_text : {};
  const zrName = (ZR.find(x => s(x.wert) === s(B.zeitraum)) || ZR[0]).text;
  const zustName = (ZUST.find(x => x.wert === s(B.versand)) || ZUST[0]).text;
  kopf.titel = s(B.name);
  kopf.beschreibung = zusammen(B.standard ? 'Standard-Analyse' : (B.von ? 'angelegt von ' + s(B.von) : ''), s(B.zeitplan), zrName, anzE(EL.length), B.geloescht ? 'im Papierkorb' : '');
  kopf.krumen = krumen0.concat([{ text: titel, ziel: hier() }].concat(B.geloescht ? [{ text: 'Papierkorb', ziel: hier({ papierkorb: '1' }) }] : []).concat([{ text: s(B.name) }]));
  if (B.geloescht) kopf.hauptaktion = B.darf_aendern ? { text: 'Wiederherstellen', aktion: 'bf_wiederherstellen', werte: w,
    frage: 'KI-Analyse „' + s(B.name) + '“ wiederherstellen? Danach erstellt Ally sie wieder nach ihrem Zeitplan.' } : undefined;
  else {
    // „Jetzt erstellen“: zeigt die Einstellungen kurz an, danach entsteht das Ergebnis und steht auf dieser Seite (Koordinator 30.10.2026)
    if (B.darf_erstellen === true) {
      kopf.hauptaktion = { text: 'Jetzt erstellen', fenster: 'jetzt' };
      const fuerMich = B.ich_empfaenger ? (B.versand === 'chat' ? 'auf dieser Seite und im Chat, soweit eingerichtet' : B.versand === 'mail' ? 'auf dieser Seite und per Mail, soweit eingerichtet' : 'nur auf dieser Seite')
        : 'nur auf dieser Seite (du bist nicht unter den Empfängern)';
      // Layout 5 (Plan 31): Hinweis am i des Fenstertitels (Baustein „hinweis“, hinweiseAlsInfo); vorher info am Formular ohne Titel, nicht angezeigt
      fenster.push({ id: 'jetzt', art: 'dialog', titel: 'Jetzt erstellen', inhalt: [
        { typ: 'hinweis', text: 'Ally erstellt das Ergebnis jetzt für dich; der Zeitplan bleibt, wie er ist. Das kann einige Sekunden dauern.' },
        { typ: 'paare', eintraege: [{ label: 'Zeitraum', wert: s(Z.text) ? s(Z.text) + ' verglichen mit ' + s(Z.vergleich_text) : zrName },
          { label: 'Talents', wert: 'deine eigenen' + (L(B.talents_namen).length ? ' und ' + L(B.talents_namen).map(s).join(', ') : '') },
          { label: 'Ergebnis', wert: fuerMich },
          { label: 'Zeitplan', wert: s(B.zeitplan) + (B.naechster ? ', nächste am ' + s(B.naechster) : '') }] },
        { typ: 'formular', id: 'jetzt', aktion: 'bf_jetzt', werte: w, spalten: 1, felder: [],
          knoepfe: [{ text: 'Abbrechen', art: 'neben', schliesst: true }, { text: 'Jetzt erstellen' }] }] });
    }
    if (darf) kopf.aktionen = [{ text: 'In den Papierkorb', aktion: 'bf_papierkorb', werte: w,
      frage: 'KI-Analyse „' + s(B.name) + '“ in den Papierkorb legen? Ally erstellt sie dann nicht mehr, auch nicht nach Zeitplan. Im Papierkorb kannst du sie wiederherstellen oder endgültig löschen.' }];
  }
  bloecke = [{ typ: 'kennzahlen', eintraege: [
    { label: 'Nächste nach Zeitplan', wert: B.naechster ? s(B.naechster).split(', ').slice(0, 2).join(', ') : 'nur von Hand', neben: B.naechster ? s(B.naechster).split(', ')[2] || '' : 'mit „Jetzt erstellen“' },
    { label: 'Empfänger', wert: String(EL.length), neben: OHNE.length ? OHNE.length + ' gewählte ohne KI-Analyse' : '', ton: OHNE.length ? 'warn' : '' },
    { label: 'Zuletzt erstellt', wert: ER.length ? s(ER[0].erstellt_am).split(' ')[0] : '–', neben: ER.length ? s(ER[0].erstellt_am).split(' ')[1] || '' : 'noch nie' }] }];
  // Ergebnis (von Stefan bestätigter Kopf): erstellt am, erstellt von, Zeitraum mit Vergleich, Talents (auch ohne Zahlen), Stand der Zahlen, Zustellung, KI; darunter der volle Text
  const EG = B.ergebnis && typeof B.ergebnis === 'object' && id12(B.ergebnis.id) ? B.ergebnis : null;
  abschnitte.push({ id: 'ergebnis', titel: EG && ER.length && s(ER[0].id) !== s(EG.id) ? 'Ergebnis vom ' + s(EG.erstellt_am) : 'Ergebnis', offen_standard: true,
    info: ['Das neueste Ergebnis, das du lesen darfst; ältere stehen im Verlauf. Lesen darf ein Ergebnis die Person, für die es erstellt wurde, und wer die Analyse ändern darf und alle ihre Talents sieht.'],
    inhalt: EG ? [{ typ: 'paare', eintraege: [{ label: 'Erstellt am', wert: s(EG.erstellt_am) }, { label: 'Erstellt von', wert: s(EG.erstellt_von) }]
        .concat(s(EG.person) !== s(R.ich) ? [{ label: 'Für', wert: s(EG.fuer) }] : [])
        .concat([{ label: 'Zeitraum der Daten', wert: s(EG.zeitraum) }, { label: 'Talents', wert: s(EG.talents) }, { label: 'Stand der Zahlen', wert: s(EG.stand_zahlen) },
          { label: 'Zugestellt', wert: s(EG.zugestellt), ton: EG.zustell_warn === true ? 'warn' : '' }, { label: 'KI', wert: s(EG.ki), ton: EG.ki_ok === false ? 'warn' : '' }]) }]
        .concat(bausteine(EG.text))
      : [{ typ: 'text', ton: 'grau', text: B.darf_erstellen === true ? 'Noch kein Ergebnis. „Jetzt erstellen“ erstellt es sofort.' : 'Noch kein Ergebnis für dich.' }] });
  // Kacheln (Stefan 29.10.2026, 16:13): je Bereich ein eigenes Formular mit Aktion = Kachel mit Stand und „Ändern“, der Bereich klappt darunter auf.
  // Ohne Ändern-Recht (und im Papierkorb) gesperrte Formulare mit „Anzeigen“ wie fixierte Einstellungen (B8b).
  const kachel = (id, felder, extra) => Object.assign({ typ: 'formular', id: 'b-' + id, aktion: 'bf_speichern', werte: Object.assign({ teil: id }, w), spalten: 2, felder },
    darf ? {} : { gesperrt: true }, extra || {});
  const sperren = f => darf ? f : f.typ === 'mehrfach' ? Object.assign({}, f, { optionen: L(f.optionen).map(o => Object.assign({}, o, { gesperrt: true })) }) : Object.assign({}, f, { gesperrt: true });
  const anzeigen = darf ? {} : { kachel_aktion: 'Anzeigen' };
  const TO = L(R.auswahl_talents), PO = L(R.auswahl_personen);
  const WT = L(B.talents_namen).map(s).concat(L(B.talents).length > L(B.talents_namen).length ? [(L(B.talents).length - L(B.talents_namen).length) + ' weitere'] : []);
  // 1. Name, Talents und Zeitraum
  abschnitte.push(Object.assign({ id: 'inhalt', titel: 'Name, Talents und Zeitraum', offen_standard: false,
    info: ['Die Zahlen je Talent im Zeitraum, was auffällt und worum sich die Person kümmern sollte, mit Einordnung durch die KI; höchstens 10 Talents im Text, im Kopf alle.', TAL_INFO],
    inhalt: [{ typ: 'paare', eintraege: [{ label: 'Zeitraum', wert: zrName + (s(Z.text) ? ' (' + s(Z.text) + ')' : '') }, { label: 'Weitere Talents', wert: WT.length ? WT.join(', ') : 'keine' }] },
      kachel('inhalt', [
      sperren({ typ: 'text', name: 'name', label: 'Name', wert: s(B.name), pflicht: true, max: '80', breite: 'voll', info: 'So heißt die KI-Analyse auf dieser Seite, im Chat und im Dashboard.' }),
      sperren({ typ: 'auswahl', name: 'zeitraum', label: 'Zeitraum der Daten', breite: 'voll', ausklappliste: true, wert: s(B.zeitraum || 'letzte_7_tage'), optionen: ZR.map(x => ({ wert: s(x.wert), text: s(x.text) })), info: ZEIT_INFO }),
      darf ? { typ: 'mehrfach', name: 'talents', label: 'Weitere Talents', breite: 'voll', wert: L(B.talents).map(s), info: TAL_INFO, optionen: gewZuerst(TO.map(t => ({ wert: s(t.wert), text: s(t.text) })), B.talents) }
        : { typ: 'text', name: 'talents_anzeige', label: 'Weitere Talents', wert: WT.length ? WT.join(', ') : 'keine', gesperrt: true, breite: 'voll' }])] }, anzeigen));
  // 2. Zeitplan (Standard-Analyse: Tag und Uhrzeit auch unter Einstellungen › KI-Funktionen; fixiert = gesperrte Felder mit „Fixiert.“ wie in den Einstellungen, B8b)
  const fix = f => B.fixiert ? Object.assign({}, f, { gesperrt: true, neben: 'Fixiert.' }) : sperren(f);
  abschnitte.push(Object.assign({ id: 'zeitplan', titel: 'Zeitplan', offen_standard: false,
    info: [PLAN_INFO].concat(B.standard ? ['Tag und Uhrzeit der Standard-Analyse stehen auch unter Einstellungen › KI-Funktionen.'] : [])
      .concat(B.fixiert ? ['Fixierte Werte ändert nur eine Person mit der Rolle Superadmin.'] : []),
    inhalt: [{ typ: 'paare', eintraege: [{ label: 'Zeitplan', wert: s(B.zeitplan) }].concat(B.naechster ? [{ label: 'Nächste nach Zeitplan', wert: s(B.naechster) }] : []) },
      kachel('zeitplan', planFelder(B, fix), B.fixiert ? { gesperrt: true } : {})] }, darf && !B.fixiert ? {} : { kachel_aktion: 'Anzeigen' }));
  // 3. Empfänger
  const empfText = EL.map(e => s(e.name) + (Number(e.talents) > 0 ? ' (' + (Number(e.talents) === 1 ? '1 Talent' : Number(e.talents) + ' Talents') + ')' : '')).join(', ');
  const EMPF_OPT = (B.darf_zustaendige === true ? [{ wert: 'zustaendige', text: 'Zuständige und gewählte Personen' }] : []).concat([{ wert: 'personen', text: 'Nur gewählte Personen' }]);
  abschnitte.push(Object.assign({ id: 'empfaenger', titel: 'Empfänger', offen_standard: false,
    info: ['Für jede Person entsteht ein eigenes Ergebnis mit ihren Talents. Wer unter Einstellungen › Benachrichtigungen die KI-Analysen ausschaltet, bekommt keine.',
      'Zuständige: die Manager/innen, die für die Talents der Agentur zuständig sind; wählen kann das nur, wer alle KI-Analysen sieht.'],
    inhalt: [{ typ: 'paare', eintraege: [{ label: 'Bekommen sie', wert: anzE(EL.length) }, { label: 'Wer', wert: empfText || 'niemand' }]
        .concat(OHNE.length ? [{ label: 'Bekommen nichts', wert: OHNE.map(o => s(o.name) + ' (' + s(o.grund) + ')').join(', ') }] : []) },
      kachel('empfaenger', [
        EMPF_OPT.length > 1 || !darf ? sperren({ typ: 'auswahl', name: 'empfaenger', label: 'Empfänger', breite: 'voll', wert: s(B.empfaenger),
          optionen: darf ? EMPF_OPT : [{ wert: 'zustaendige', text: 'Zuständige und gewählte Personen' }, { wert: 'personen', text: 'Nur gewählte Personen' }] })
          : { typ: 'versteckt', name: 'empfaenger', wert: 'personen' }]
        .concat(darf ? [{ typ: 'mehrfach', name: 'personen', label: 'Personen', breite: 'voll', wert: L(B.personen).map(s), info: 'Höchstens 20.',
          optionen: gewZuerst(PO.map(p => ({ wert: s(p.wert), text: s(p.text), neben: s(p.neben) })), B.personen) }] : []))] }, anzeigen));
  // 4. Zustellung: nur in Ally (Standard), Chat oder Mail; Mail wie bei den Verkaufsberichten (Absender-Postfach, Betreff, Text, Signatur, KI-Hinweis)
  const mitMail = B.versand === 'mail';
  const AS = B.absender_stand && typeof B.absender_stand === 'object' ? B.absender_stand : {};
  const STD = B.mail_standard && typeof B.mail_standard === 'object' ? B.mail_standard : {};
