  const anM = { feld: 'versand', werte: ['mail'] };
  const vStand = [{ label: 'Zustellung', wert: zustName }]
    .concat(mitMail && AS.bereit === false ? [{ label: 'Mail', wert: 'Es geht noch keine Mail raus: ' + s(AS.fehlt) }] : [])
    .concat(mitMail && B.testdaten ? [{ label: 'Testdaten', wert: 'nur Testmodus, es geht keine Mail raus' }] : [])
    .concat(mitMail ? [{ label: 'Absender', wert: B.absender ? absName(B.absender) : AS.weg === 'system' ? 'Absender für Systemnachrichten (' + s(AS.adresse) + ')' : 'nicht gewählt' },
      { label: 'Betreff', wert: B.mail_betreff ? 'eigener Betreff' : 'Standardbetreff' },
      { label: 'Signatur', wert: sigArt === 'keine' ? 'keine' : sigArt === 'eigen' ? 'eigene Signatur' : 'Standardsignatur des Absenders' },
      { label: 'KI-Hinweis', wert: B.ki_hinweis ? 'an' : 'aus' }] : []);
  abschnitte.push(Object.assign({ id: 'versand', titel: 'Zustellung', offen_standard: false,
    info: [ZUST_INFO, 'Ist bei einer Person kein Chat bzw. keine Mail-Adresse eingerichtet, steht das Ergebnis für sie nur in Ally.'],
    inhalt: [{ typ: 'paare', eintraege: vStand },
      kachel('versand', [
        sperren({ typ: 'auswahl', name: 'versand', label: 'Zustellung', breite: 'voll', wert: s(B.versand || 'ally'), optionen: ZUST }),
        sperren({ typ: 'auswahl', name: 'absender', label: 'Absender-Postfach', breite: 'voll', ausklappliste: true, wert: s(B.absender || ''), zeigen_wenn: anM, optionen: absOpt(), info: ABS_INFO }),
        sperren({ typ: 'text', name: 'mail_betreff', label: 'Betreff der Mail', wert: s(B.mail_betreff || STD.betreff || ''), breite: 'voll', max: '200', zeigen_wenn: anM,
          info: 'Platzhalter in geschweiften Klammern, z. B. {Titel} oder {Zeitraum}, setzt Ally beim Versand ein. Leer gespeichert gilt wieder der Standardbetreff.' }),
        darf ? { typ: 'signatur', name: 'mail_html', label: 'Text vor der KI-Analyse', wert: s(B.mail_html || STD.html || ''), einfuegen: EIN, zeigen_wenn: anM,
            info: 'Steht in der Mail über der KI-Analyse der Person. Leer gespeichert gilt wieder der Standardtext.' }
          : { typ: 'text', name: 'mail_html_anzeige', label: 'Text vor der KI-Analyse', wert: B.mail_html ? 'eigener Text' : 'Standardtext', gesperrt: true, breite: 'voll', zeigen_wenn: anM },
        sperren({ typ: 'auswahl', name: 'signatur', label: 'Signatur', breite: 'voll', ausklappliste: true, wert: sigArt, zeigen_wenn: anM,
          optionen: [{ wert: 'postfach', text: 'Standardsignatur des Absenders' }, { wert: 'eigen', text: 'Eigene Signatur für diese KI-Analyse' }, { wert: 'keine', text: 'Keine Signatur' }] }),
        darf ? { typ: 'signatur', name: 'signatur_html', label: 'Eigene Signatur', wert: s(B.signatur_html || (ABS.find(a => s(a.adresse) === s(B.absender)) || (B.absender ? {} : SYSA) || {}).signatur || ''),
            einfuegen: { label: 'Platzhalter einfügen', optionen: [{ wert: '{Name}', text: 'Name', info: 'Name der Person, die die KI-Analyse zuletzt gespeichert bzw. „Jetzt erstellen“ gewählt hat' }] },
            zeigen_wenn: [anM, { feld: 'signatur', werte: ['eigen'] }], info: 'Gilt nur für diese KI-Analyse. Startet mit der Signatur des Absender-Postfachs.' } : null,
        sperren({ typ: 'haken', name: 'ki_hinweis', label: 'KI-Hinweis anhängen', an: B.ki_hinweis === true, breite: 'voll', zeigen_wenn: anM,
          info: 'Hängt unten an die Mail den Satz „Erstellt mit KI-Unterstützung.“ an. Gilt nur für diese KI-Analyse.' })].filter(Boolean))] }, anzeigen));
  // 5. Teilen (Stefan 30.10.2026: „es wird einfach nur etwas geteilt“; nur wer ändern darf)
  if (darf) {
    const FR = L(B.freigaben), FA = L(R.auswahl_freigabe);
    abschnitte.push({ id: 'freigabe', titel: 'Teilen', offen_standard: false,
      info: ['Standardmäßig sehen eine KI-Analyse nur, wer sie angelegt hat, und ihre Empfänger. Hier teilst du sie mit weiteren Personen. Sie sehen sie, ändern kann sie nur, wer sie angelegt hat.',
        'Zur Auswahl stehen Personen mit dem Recht „KI-Analysen“, mit denen sie noch nicht geteilt ist. Empfänger sehen sie ohnehin, solange sie sie bekommen.'],
      inhalt: [{ typ: 'paare', eintraege: [{ label: 'Geteilt mit', wert: FR.length ? FR.map(f => s(f.name)).join(', ') : 'niemandem' }] },
        { typ: 'formular', id: 'freigeben', aktion: 'bf_freigeben', werte: w, spalten: 1, knoepfe: [{ text: 'Teilen' }],
          felder: [FA.length ? { typ: 'auswahl', name: 'person', label: 'Teilen mit …', breite: 'voll', wert: '', ausklappliste: true, pflicht: true,
              optionen: [{ wert: '', text: 'Person wählen' }].concat(FA.map(p => ({ wert: s(p.wert), text: s(p.text) }))) }
            : { typ: 'text', name: 'person_anzeige', label: 'Teilen mit …', wert: 'Alle Personen mit dem Recht „KI-Analysen“ sehen sie schon.', gesperrt: true, breite: 'voll' }] }]
        .concat(FR.length ? [{ typ: 'liste', eintraege: FR.map(f => ({ fett: s(f.name), neben: zusammen('geteilt ' + s(f.am), f.von ? 'von ' + s(f.von) : ''),
          aktion: { text: 'Nicht mehr teilen', aktion: 'bf_freigabe_entfernen', werte: { briefing_id: bid, person: s(f.person) },
            frage: 'Mit ' + s(f.name) + ' nicht mehr teilen? ' + s(f.name) + ' sieht die KI-Analyse danach nicht mehr, außer als Empfänger.' } })) }] : []) });
    if (!FA.length) abschnitte[abschnitte.length - 1].inhalt[1].gesperrt = true;
  }
  // i der Kacheln: im Kachel-Aufbau steht der Hinweis als Baustein „hinweis“ im Bereich, der Baukasten setzt ihn ins i an dessen Überschrift (hinweiseAlsInfo)
  for (const ab of abschnitte) if (['inhalt', 'zeitplan', 'empfaenger', 'versand', 'freigabe'].includes(ab.id)) ab.inhalt = [{ typ: 'hinweis', text: L(ab.info).join(' ') }].concat(ab.inhalt);
  // 6. Verlauf: alle lesbaren Ergebnisse mit Kopf; „Lesen“ zeigt das Ergebnis oben mit vollem Text
  abschnitte.push({ id: 'verlauf', titel: 'Verlauf', zahl: String(Number(B.ergebnisse_anzahl || ER.length)), offen_standard: false,
    info: ['Alle Ergebnisse dieser KI-Analyse, die du lesen darfst (die neuesten 50), mit vollem Text.'],
    inhalt: [{ typ: 'tabelle', id: 'ergebnisse', titel: 'Verlauf', spalten: [{ schluessel: 'am', titel: 'Erstellt am' }, { schluessel: 'fuer', titel: 'Für' },
      { schluessel: 'von', titel: 'Erstellt von' }, { schluessel: 'zu', titel: 'Zugestellt' }, { schluessel: 'ki', titel: 'KI' }],
      zeilen: ER.filter(x => id12(x.id)).map(x => ({ id: id12(x.id), aktiv: EG && s(EG.id) === s(x.id), zellen: { am: { text: s(x.erstellt_am), ziel: hier({ briefing: bid, ergebnis: id12(x.id) }) },
        fuer: s(x.fuer), von: s(x.erstellt_von), zu: x.zustell_warn === true ? { text: s(x.zugestellt), ton: 'warn' } : s(x.zugestellt),
        ki: x.ki_ok === false ? { text: s(x.ki), ton: 'warn' } : s(x.ki) } })),
      sortierung: {}, seite: 1, je_seite: 20, gesamt: ER.length, leer: 'Noch keine Ergebnisse.' }] });
} else if (P.papierkorb === '1') {
  // ---------- Papierkorb ----------
  const PK = L(R.papierkorb).filter(x => x && id9(x.id));
  kopf.titel = 'Papierkorb';
  kopf.beschreibung = 'KI-Analysen im Papierkorb erstellt Ally nicht mehr. Du kannst sie wiederherstellen oder endgültig löschen.';
  kopf.krumen = krumen0.concat([{ text: titel, ziel: hier() }, { text: 'Papierkorb' }]);
  const erg = n => Number(n) === 1 ? '1 Ergebnis' : Number(n || 0) + ' Ergebnisse';
  abschnitte = [{ id: 'papierkorb', titel: 'Im Papierkorb', zahl: String(PK.length), offen_standard: true,
    inhalt: [{ typ: 'tabelle', id: 'papierkorb', titel: 'Im Papierkorb', spalten: [{ schluessel: 'name', titel: 'KI-Analyse' }, { schluessel: 'geloescht', titel: 'Gelöscht' }, { schluessel: 'aktion', titel: 'Aktion' }],
      zeilen: PK.map(x => ({ zellen: { name: { text: s(x.name), ziel: hier({ briefing: id9(x.id) }), neben: zusammen(x.standard ? 'Standard-Analyse' : '', erg(x.ergebnisse)) },
        geloescht: { text: s(x.geloescht), neben: x.von ? 'von ' + s(x.von) : '' },
        aktion: { aktionen: [
          { text: 'Wiederherstellen', aktion: 'bf_wiederherstellen', werte: { briefing_id: id9(x.id) }, frage: 'KI-Analyse „' + s(x.name) + '“ wiederherstellen? Danach erstellt Ally sie wieder nach ihrem Zeitplan.' },
          { text: 'Endgültig löschen', aktion: 'bf_endgueltig', werte: { briefing_id: id9(x.id) },
            frage: 'KI-Analyse „' + s(x.name) + '“ endgültig löschen? Sie wird mit ' + (Number(x.ergebnisse) ? 'allen ' + erg(x.ergebnisse) : 'Teilen und Verlauf') + ' gelöscht und lässt sich nicht wiederherstellen.'
              + (x.standard ? ' Ally legt die Standard-Analyse danach nicht neu an.' : '') }] } } })),
      sortierung: {}, seite: 1, je_seite: 50, gesamt: PK.length, leer: 'Der Papierkorb ist leer.' }] }];
} else {
  // ---------- Liste ----------
  const BE = L(R.liste).filter(x => x && id9(x.id));
  if (R.darf_anlegen === true) {
    kopf.hauptaktion = { text: 'Neue Analyse', fenster: 'neu' };
    // Layout 5 (Plan 31, E9): Kopf-Knöpfe ohne Zähler, auch nicht „Papierkorb“ (der Baukasten zeigt ihn dann als Symbol, Stefan 24.10.2026, 14:24)
    kopf.knoepfe = [{ text: 'Papierkorb', ziel: hier({ papierkorb: '1' }) }];
    // Einstellungen zuerst (Stefan 30.10.2026: „das muss alles vorher passieren“); „Erstellen“ legt an und zeigt sofort das Ergebnis
    const TO = L(R.auswahl_talents), PO = L(R.auswahl_personen);
    const ID = (f, x) => f;
    // neu=1: aus dem Dashboard (Link „Neue Analyse“) gleich mit den Einstellungen öffnen; beim Schließen ohne den Parameter
    fenster.push(Object.assign({ id: 'neu', art: 'dialog', titel: 'Neue Analyse' }, P.neu === '1' ? { offen: true, schliessen_ziel: hier() } : {}, { inhalt: [
      { typ: 'formular', id: 'neu', aktion: 'bf_anlegen', spalten: 2, felder: [
        { typ: 'text', name: 'name', label: 'Name', pflicht: true, max: '80', breite: 'voll', platzhalter: 'z. B. Montagsüberblick', info: 'So heißt die KI-Analyse auf der Seite, im Chat und im Dashboard.' },
        { typ: 'mehrfach', name: 'talents', label: 'Weitere Talents', breite: 'voll', wert: [], info: TAL_INFO + (TO.some(t => t.eigen === true) ? ' Deine eigenen: ' + TO.filter(t => t.eigen === true).map(t => s(t.text)).join(', ') + '.' : ''),
          optionen: TO.filter(t => t.eigen !== true).map(t => ({ wert: s(t.wert), text: s(t.text) })) },
        { typ: 'auswahl', name: 'zeitraum', label: 'Zeitraum der Daten', breite: 'voll', ausklappliste: true, wert: 'letzte_7_tage', optionen: ZR.map(x => ({ wert: s(x.wert), text: s(x.text) })), info: ZEIT_INFO }]
        .concat(planFelder({ intervall: 'aus', tag: 1, uhrzeit: '08:00' }, ID))
        .concat([R.darf_zustaendige === true ? { typ: 'auswahl', name: 'empfaenger', label: 'Empfänger', breite: 'voll', wert: 'personen',
            optionen: [{ wert: 'personen', text: 'Nur gewählte Personen' }, { wert: 'zustaendige', text: 'Zuständige und gewählte Personen' }],
            info: 'Für jede Person entsteht ein eigenes Ergebnis mit ihren Talents. Zuständige: die Manager/innen, die für die Talents der Agentur zuständig sind.' }
          : { typ: 'versteckt', name: 'empfaenger', wert: 'personen' },
          { typ: 'mehrfach', name: 'personen', label: 'Personen', breite: 'voll', wert: [s(R.ich)], info: 'Höchstens 20. Du bist vorausgewählt.',
            optionen: gewZuerst(PO.map(p => ({ wert: s(p.wert), text: s(p.text), neben: s(p.neben) })), [s(R.ich)]) },
          { typ: 'auswahl', name: 'versand', label: 'Zustellung', breite: 'voll', wert: 'ally', optionen: ZUST, info: ZUST_INFO },
          { typ: 'auswahl', name: 'absender', label: 'Absender-Postfach', breite: 'voll', ausklappliste: true, wert: '', zeigen_wenn: { feld: 'versand', werte: ['mail'] }, optionen: absOpt(),
            info: ABS_INFO + ' Betreff, Text und Signatur der Mail stellst du danach in der Kachel „Zustellung“ ein.' }]),
        knoepfe: [{ text: 'Abbrechen', art: 'neben', schliesst: true }, { text: 'Erstellen' }] }] }));
  }
  const wer = x => x.standard ? 'Standard-Analyse' : x.eigen ? 'von dir angelegt' : x.freigegeben ? 'mit dir geteilt' + (x.von ? ' von ' + s(x.von) : '') : x.von ? 'von ' + s(x.von) : '';
  abschnitte = [{ id: 'briefings', titel: 'KI-Analysen', zahl: String(BE.length), offen_standard: true,
    info: [(R.reichweite === 'alle' ? 'Du siehst alle KI-Analysen.' : 'Du siehst die KI-Analysen, die du angelegt hast, die du bekommst und die mit dir geteilt sind.')
      + ' Eine KI-Analyse ordnet die Zahlen der Talents im gewählten Zeitraum mit KI ein, verglichen mit dem Zeitraum davor. Das Ergebnis steht hier; in den Chat oder per Mail nur, wenn das so eingestellt ist.'],
    inhalt: [{ typ: 'tabelle', id: 'briefings', titel: 'KI-Analysen', spalten: [{ schluessel: 'name', titel: 'KI-Analyse' }, { schluessel: 'zeitplan', titel: 'Zeitplan' },
      { schluessel: 'empfaenger', titel: 'Empfänger' }, { schluessel: 'letzter', titel: 'Zuletzt' }, { schluessel: 'aktion', titel: 'Aktion' }],
      zeilen: BE.map(x => ({ zellen: { name: { text: s(x.name), ziel: hier({ briefing: id9(x.id) }), neben: wer(x) }, zeitplan: s(x.zeitplan),
        empfaenger: { text: anzE(x.empfaenger_zahl), neben: x.empfaenger_art === 'zustaendige' ? 'zuständige Manager/innen' : 'gewählte Personen' },
        letzter: x.letzter ? s(x.letzter) : { text: 'noch nie', ton: 'grau' },
        aktion: { aktionen: [{ text: 'Öffnen', ziel: hier({ briefing: id9(x.id) }) }].concat(x.darf_aendern === true ? [{ text: 'In den Papierkorb', aktion: 'bf_papierkorb',
          werte: { briefing_id: id9(x.id) }, frage: 'KI-Analyse „' + s(x.name) + '“ in den Papierkorb legen? Ally erstellt sie dann nicht mehr, auch nicht nach Zeitplan. Im Papierkorb kannst du sie wiederherstellen oder endgültig löschen.' }] : []) } } })),
      sortierung: {}, seite: 1, je_seite: 50, gesamt: BE.length, leer: R.darf_anlegen === true ? 'Noch keine KI-Analysen. Über „Neue Analyse“ legst du die erste an.' : 'Noch keine KI-Analysen.' }] }];
}
const inhalt = { seite: kopf, fenster };
if (bloecke) inhalt.bloecke = bloecke;
if (abschnitte.length) inhalt.abschnitte = abschnitte;
return [{ json: { inhalt } }];
